    40  void UA_WorkQueue_cleanup(UA_WorkQueue *wq) {
    41  #ifdef UA_ENABLE_MULTITHREADING
    42      /* Shut down workers */
    43      UA_WorkQueue_stop(wq);
    44
    45      /* Execute remaining work in the dispatch queue */
    46      while(true) {
    47          pthread_mutex_lock(&wq->dispatchQueue_accessMutex);
    48          UA_DelayedCallback *dc = SIMPLEQ_FIRST(&wq->dispatchQueue);
    49          if(!dc) {
    50              pthread_mutex_unlock(&wq->dispatchQueue_accessMutex);
    51              break;
    52          }
    53          SIMPLEQ_REMOVE_HEAD(&wq->dispatchQueue, next);
    54          pthread_mutex_unlock(&wq->dispatchQueue_accessMutex);
    55          dc->callback(dc->application, dc->data);
    56          UA_free(dc);
    57      }
    58  #endif
    59
    60      /* All workers are shut down. Execute remaining delayed work here. */
    61      UA_WorkQueue_manuallyProcessDelayed(wq);
    62
    63  #ifdef UA_ENABLE_MULTITHREADING
    64      wq->delayedCallbacks_checkpoint = NULL;
    65      pthread_mutex_destroy(&wq->dispatchQueue_accessMutex);
    66      pthread_cond_destroy(&wq->dispatchQueue_condition);
    67      pthread_mutex_destroy(&wq->dispatchQueue_conditionMutex);
    68      pthread_mutex_destroy(&wq->delayedCallbacks_accessMutex);
