    78  static void *
    79  workerLoop(UA_Worker *worker) {
    80      UA_WorkQueue *wq = worker->queue;
    81      UA_UInt32 *counter = &worker->counter;
    82      volatile UA_Boolean *running = &worker->running;
    83
    84      /* Initialize the (thread local) random seed with the ram address
    85       * of the worker. Not for security-critical entropy! */
    86      UA_random_seed((uintptr_t)worker);
    87
    88      while(*running) {
    89          UA_atomic_addUInt32(counter, 1);
    90
    91          /* Remove a callback from the queue */
    92          pthread_mutex_lock(&wq->dispatchQueue_accessMutex);
    93          UA_DelayedCallback *dc = SIMPLEQ_FIRST(&wq->dispatchQueue);
    94          if(dc)
    95              SIMPLEQ_REMOVE_HEAD(&wq->dispatchQueue, next);
    96          pthread_mutex_unlock(&wq->dispatchQueue_accessMutex);
    97
    98          /* Nothing to do. Sleep until a callback is dispatched */
    99          if(!dc) {
   100              pthread_mutex_lock(&wq->dispatchQueue_conditionMutex);
   101              pthread_cond_wait(&wq->dispatchQueue_condition,
   102                                &wq->dispatchQueue_conditionMutex);
   103              pthread_mutex_unlock(&wq->dispatchQueue_conditionMutex);
   104              continue;
   105          }
   106
   107          /* Execute */
   108          if(dc->callback)
   109              dc->callback(dc->application, dc->data);
   110          UA_free(dc);
   111      }
   112
   113      return NULL;
   114  }
