   116  /* Can be called repeatedly and starts additional workers */
   117  UA_StatusCode
   118  UA_WorkQueue_start(UA_WorkQueue *wq, size_t workersCount) {
   119      if(wq->workersSize > 0 || workersCount == 0)
   120          return UA_STATUSCODE_BADINTERNALERROR;
   121
   122      /* Create the worker array */
   123      wq->workers = (UA_Worker*)UA_calloc(workersCount, sizeof(UA_Worker));
   124      if(!wq->workers)
   125          return UA_STATUSCODE_BADOUTOFMEMORY;
   126      wq->workersSize = workersCount;
   127
   128      /* Spin up the workers */
   129      for(size_t i = 0; i < workersCount; ++i) {
   130          UA_Worker *w = &wq->workers[i];
   131          w->queue = wq;
   132          w->counter = 0;
   133          w->running = true;
   134          pthread_create(&w->thread, NULL, (void* (*)(void*))workerLoop, w);
   135      }
   136      return UA_STATUSCODE_GOOD;
   137  }
