   757  void
   758  UA_Server_processBinaryMessage(UA_Server *server, UA_Connection *connection,
   759                                 UA_ByteString *message) {
   760      UA_LOG_TRACE(server->config.logger, UA_LOGCATEGORY_NETWORK,
   761                   "Connection %i | Received a packet.", connection->sockfd);
   762  #ifdef UA_DEBUG_DUMP_PKGS
   763      UA_dump_hex_pkg(message->data, message->length);
   764  #endif
   765
   766      UA_StatusCode retval = UA_Connection_processChunks(connection, server,
   767                                                         processCompleteChunk, message);
   768      if(retval != UA_STATUSCODE_GOOD) {
   769          UA_LOG_INFO(server->config.logger, UA_LOGCATEGORY_NETWORK,
   770                      "Connection %i | Processing the message failed with "
   771                      "error %s", connection->sockfd, UA_StatusCode_name(retval));
   772          /* Send an ERR message and close the connection */
   773          UA_TcpErrorMessage error;
   774          error.error = retval;
   775          error.reason = UA_STRING_NULL;
   776          UA_Connection_sendError(connection, &error);
   777          connection->close(connection);
   778          return;
   779      }
   780
   781      if(!connection->channel)
   782          return;
   783
   784      /* Process complete messages */
   785      UA_SecureChannel_processCompleteMessages(connection->channel, server,
   786                                               processSecureChannelMessage);
   787
   788      /* Store unused chunks internally in the SecureChannel */
   789      UA_SecureChannel_persistIncompleteMessages(connection->channel);
   790  }
